import{_ as t,o as a,c as s,a2 as i}from"./chunks/framework.B8TleWq7.js";const g=JSON.parse('{"title":"Update Keel","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/update-keel.md","filePath":"getting-started/update-keel.md"}'),d={name:"getting-started/update-keel.md"};function o(n,e,l,h,r,c){return a(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="update-keel" tabindex="-1">Update Keel <a class="header-anchor" href="#update-keel" aria-label="Permalink to &quot;Update Keel&quot;">​</a></h1><p>A game stays on one Keel version until you choose to move it. Run these from the <strong>game&#39;s</strong> root folder (the one with <code>src/</code>).</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/keel.js</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> v0.2.0</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       # a specific tag, or: latest</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/keel.js</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">              # installed version, and any Keel file edited by hand</span></span></code></pre></div><h2 id="update" tabindex="-1">update <a class="header-anchor" href="#update" aria-label="Permalink to &quot;update&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>node tools/keel.js update &lt;tag|latest&gt; [--from &lt;path&gt;] [--force]</span></span></code></pre></div><p>It downloads the tag, overwrites every owned file, and prints a summary (the numbers here are an example):</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>keel: now Keel 0.2.0 (abc1234): 12 changed, 3 added, 1 removed, 214 Keel files</span></span></code></pre></div><p>Then read that version&#39;s entry in the <a href="/Keel-Docs/changelog">Changelog</a>, run the <a href="/Keel-Docs/guides/unit-tests">unit tests</a>, and commit.</p><table tabindex="0"><thead><tr><th>Flag</th><th>Meaning</th></tr></thead><tbody><tr><td><code>--from &lt;path&gt;</code></td><td>Use a local Keel checkout instead of cloning from GitHub.</td></tr><tr><td><code>--force</code></td><td>Overwrite even if owned files were edited, or adopt a game with no <code>keel.json</code>.</td></tr></tbody></table><h3 id="what-it-replaces" tabindex="-1">What it replaces <a class="header-anchor" href="#what-it-replaces" aria-label="Permalink to &quot;What it replaces&quot;">​</a></h3><ul><li>Files inside owned <strong>folders</strong> are overwritten in place, and a file Keel dropped is deleted (with any folder left empty). The folders themselves are never deleted, so Studio&#39;s Script Sync stays connected. (Before 0.2.2 the folders were deleted and recreated, which broke the connection: the first update <em>to</em> 0.2.2 still does that once, so reconnect Script Sync after it.)</li><li>Owned <strong>files</strong> (such as <code>tools/keel.js</code>) are overwritten.</li><li>Starter files are never touched.</li></ul><h3 id="if-it-refuses" tabindex="-1">If it refuses <a class="header-anchor" href="#if-it-refuses" aria-label="Permalink to &quot;If it refuses&quot;">​</a></h3><p><code>update</code> stops, changing nothing, in these cases:</p><table tabindex="0"><thead><tr><th>Message</th><th>Cause</th><th>Fix</th></tr></thead><tbody><tr><td><code>Keel files were edited in this game (they would be lost)</code> and a list</td><td>An owned file no longer matches its recorded hash.</td><td>Move the change into the Keel repo, or run again with <code>--force</code> to discard it.</td></tr><tr><td><code>no keel.json here: this game has not been installed by keel.js</code></td><td>The game was not created by <code>keel.js new</code>.</td><td>See below.</td></tr><tr><td><code>this is the Keel repo itself</code></td><td>You ran it in the Keel checkout.</td><td>Keel is edited there, not updated.</td></tr><tr><td><code>run this from the game&#39;s root folder</code></td><td>No <code>src/</code> in the current folder.</td><td><code>cd</code> into the game.</td></tr></tbody></table><h3 id="adopt-a-game-that-has-no-keel-json" tabindex="-1">Adopt a game that has no keel.json <a class="header-anchor" href="#adopt-a-game-that-has-no-keel-json" aria-label="Permalink to &quot;Adopt a game that has no keel.json&quot;">​</a></h3><p>Run <code>update</code> once with <code>--force</code>. It overwrites the Keel files and writes <code>keel.json</code>:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/keel.js</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> v0.1.1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --force</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">Warning</p><p><code>--force</code> discards local edits to owned files. Check <code>git status</code> first.</p></div><h2 id="status" tabindex="-1">status <a class="header-anchor" href="#status" aria-label="Permalink to &quot;status&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>keel: Keel 0.2.0 (abc1234), 212 files, none edited</span></span></code></pre></div><p>or, if something was edited:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>keel: Keel 0.2.0 (abc1234), 212 files, 1 edited:</span></span>
<span class="line"><span>  src/ReplicatedStorage/Keel/Signal.luau</span></span></code></pre></div><p>A file that was deleted shows as <code>… (missing)</code>.</p><div class="info custom-block"><p class="custom-block-title">Note</p><p>Keel itself is changed only in the Keel repo. How to publish a new version: <a href="/Keel-Docs/guides/releasing-keel">Releasing Keel</a>.</p></div>`,24)])])}const u=t(d,[["render",o]]);export{g as __pageData,u as default};
